D="deploy orders -n s05-init"
check "Service orders-db exposes the database on port 6379 with an endpoint" '[ "$(jp svc orders-db -n s05-init "{.spec.ports[0].port}")" = 6379 ] && kubectl -n s05-init get endpointslice -l kubernetes.io/service-name=orders-db -o jsonpath="{.items[*].endpoints[*].addresses[*]}" | grep -q .'
check "Deployment orders is available" 'kubectl -n s05-init rollout status deploy/orders --timeout=90s && [ "$(jp $D "{.status.availableReplicas}")" = 1 ]'
check "container orders logs 'migration done'" 'kubectl -n s05-init logs deploy/orders -c orders | grep -qx "migration done"'
check "migrate and orders share a volume at /work" 'v1=$(jp $D "{.spec.template.spec.initContainers[?(@.name==\"migrate\")].volumeMounts[?(@.mountPath==\"/work\")].name}"); v2=$(jp $D "{.spec.template.spec.containers[?(@.name==\"orders\")].volumeMounts[?(@.mountPath==\"/work\")].name}"); [ -n "$v1" ] && [ "$v1" = "$v2" ]'
guard "init containers unchanged (names, order, commands, images)" '[ "$(jp $D "{.spec.template.spec.initContainers[*].name}")" = "wait-for-db migrate" ] && jp $D "{.spec.template.spec.initContainers[0].command[2]}" | grep -q "until nslookup orders-db.s05-init.svc.cluster.local" && [ "$(jp $D "{.spec.template.spec.initContainers[1].command[2]}")" = "echo '"'"'migration done'"'"' > /work/migrated" ] && [ "$(jp $D "{.spec.template.spec.initContainers[*].image}")" = "busybox:1.36 busybox:1.36" ]'
